sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    if (current.manager_name.preferred_language.toString() === 'fq') {
        gs.info("OHSM info HoC_PDF_Template_SetUpForEWI:assign pdf template LAB1070-ExtraPage_FQ sysid for French - " + current.number);
        //current.pdf_template = '7e5b2e281b60b450c261ed3cbc4bcbec'; // ESDCLAB1070_FQ
        current.pdf_template = '8ffcb59b1b5a2d549fde86acdd4bcbbf'; // LAB1070-ExtraPage_FQ

    } else if (current.manager_name.preferred_language.toString() === 'en') {
        gs.info("OHSM info HoC_PDF_Template_SetUpForEWI:assign pdf template ESDC-LAB1070 EN sysid for English - " + current.number);
        //current.pdf_template = '02ba665a2fcf2c904cbeb1e72799b6ce'; //ESDC-LAB1070
        current.pdf_template = '627ebc208721699050d2eca73cbb357a'; //LAB1070-ExtraPage
    } else {
        gs.info("OHSM info HoC_PDF_Template_SetUpForEWI:assign pdf template. Manager language not fq or en. Default to LAB1070-ExtraPage sysid for English - " + current.number);
        current.pdf_template = '627ebc208721699050d2eca73cbb357a'; //LAB1070-ExtraPage
    }


})(current, previous);
